import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/CTABLES-Missing-Values-for-Cell_002dDefining-Variables.md","filePath":"manual-en/CTABLES-Missing-Values-for-Cell_002dDefining-Variables.md","lastUpdated":1785684581000}'),i={name:"manual-en/CTABLES-Missing-Values-for-Cell_002dDefining-Variables.md"};function s(l,t,n,o,h,c){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h4 id="_15-7-9-1-missing-values-for-cell-defining-variables" tabindex="-1">15.7.9.1 Missing Values for Cell-Defining Variables <a class="header-anchor" href="#_15-7-9-1-missing-values-for-cell-defining-variables" aria-label="Permalink to &quot;15.7.9.1 Missing Values for Cell-Defining Variables&quot;">​</a></h4><p>For variables that divide tables into cells, per-variable category options, as described in <a href="./CTABLES-Per_002dVariable-Category-Options">CTABLES Per-Variable Category Options</a>, determine which data is analyzed. If any of the categories for such a variable would exclude a case, then that case is not included.</p><p>As an example, consider the following entirely artificial dataset, in which ‘x’ and ‘y’ are categorical variables with missing value 9, and ‘z’ is scale:</p><table tabindex="0"><thead><tr><th>x</th><th>y</th><th>z</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>1</td></tr><tr><td>1</td><td>2</td><td>10</td></tr><tr><td>1</td><td>9</td><td>100</td></tr><tr><td>2</td><td>1</td><td>1000</td></tr><tr><td>2</td><td>2</td><td>10000</td></tr><tr><td>2</td><td>9</td><td>100000</td></tr><tr><td>9</td><td>1</td><td>1000000</td></tr><tr><td>9</td><td>2</td><td>10000000</td></tr><tr><td>9</td><td>9</td><td>100000000</td></tr></tbody></table><p>Using ‘x’ and ‘y’ to define cells, and summarizing ‘z’, by default PSPP omits all the cases that have ‘x’ or ‘y’ (or both) missing:</p><pre><code>CTABLES /TABLE x &gt; y &gt; z [SUM].
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th></th><th>Sum</th></tr></thead><tbody><tr><td>x</td><td>1</td><td>y</td><td>1</td><td>z</td><td>1</td></tr><tr><td>2</td><td>z</td><td>10</td><td></td><td></td><td></td></tr><tr><td>2</td><td>y</td><td>1</td><td>z</td><td>1000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000</td><td></td><td></td><td></td></tr></tbody></table><p>If, however, we add <code>CATEGORIES</code> specifications to include missing values for ‘y’ or for ‘x’ and ‘y’, the output table includes them, like so:</p><pre><code>CTABLES /TABLE x &gt; y &gt; z [SUM] /CATEGORIES VARIABLES=y MISSING=INCLUDE.
CTABLES /TABLE x &gt; y &gt; z [SUM] /CATEGORIES VARIABLES=x y MISSING=INCLUDE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th></th><th></th><th></th><th>Sum</th></tr></thead><tbody><tr><td>x</td><td>1</td><td>y</td><td>1</td><td>z</td><td>1</td></tr><tr><td>2</td><td>z</td><td>10</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100</td><td></td><td></td><td></td></tr><tr><td>2</td><td>y</td><td>1</td><td>z</td><td>1000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100000</td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td>Sum</td></tr><tr><td>x</td><td>1</td><td>y</td><td>1</td><td>z</td><td>1</td></tr><tr><td>2</td><td>z</td><td>10</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100</td><td></td><td></td><td></td></tr><tr><td>2</td><td>y</td><td>1</td><td>z</td><td>1000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>y</td><td>1</td><td>z</td><td>1000000</td><td></td></tr><tr><td>2</td><td>z</td><td>10000000</td><td></td><td></td><td></td></tr><tr><td>9</td><td>z</td><td>100000000</td><td></td><td></td><td></td></tr></tbody></table>`,10)])])}const g=d(i,[["render",s]]);export{f as __pageData,g as default};
